package ae.vcs;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.Objects;
import java.util.Optional;

/** Loose-object directory adapter: {@code root/ab/cdef...}. Writes go temp file then atomic move. */
public final class FileObjectStore implements ObjectStore {
    private final Path root;

    public FileObjectStore(Path root) {
        this.root = Objects.requireNonNull(root);
        try {
            Files.createDirectories(root);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    Path pathOf(ObjectId id) {
        return root.resolve(id.hex().substring(0, 2)).resolve(id.hex().substring(2));
    }

    @Override
    public ObjectId put(byte[] raw) {
        Objects.requireNonNull(raw);
        ObjectId id = ObjectId.ofRaw(raw);
        Path target = pathOf(id);
        if (Files.exists(target)) {
            return id;
        }
        Path dir = target.getParent();
        Path tmp = null;
        try {
            Files.createDirectories(dir);
            tmp = Files.createTempFile(dir, ".tmp-", ".part");
            Files.write(tmp, raw, StandardOpenOption.TRUNCATE_EXISTING);
            Files.move(tmp, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            tmp = null;
            return id;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } finally {
            if (tmp != null) {
                try {
                    Files.deleteIfExists(tmp);
                } catch (IOException ignored) {
                    // best effort cleanup; the original failure is already propagating
                }
            }
        }
    }

    @Override
    public Optional<byte[]> get(ObjectId id) {
        try {
            byte[] raw = Files.readAllBytes(pathOf(id));
            if (!ObjectId.ofRaw(raw).equals(id)) {
                throw new CorruptObjectException("hash mismatch for " + id);
            }
            return Optional.of(raw);
        } catch (NoSuchFileException e) {
            return Optional.empty();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

package ae.vcs;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;

/** One small file per branch, replaced atomically. */
public final class FileRefs implements Refs {
    private final Path dir;

    public FileRefs(Path dir) {
        this.dir = Objects.requireNonNull(dir);
        try {
            Files.createDirectories(dir);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    @Override
    public synchronized Optional<ObjectId> get(String name) {
        Refs.checkName(name);
        try {
            String text = Files.readString(dir.resolve(name), StandardCharsets.US_ASCII);
            try {
                return Optional.of(ObjectId.parse(text));
            } catch (IllegalArgumentException e) {
                throw new CorruptObjectException("bad ref file for " + name);
            }
        } catch (NoSuchFileException e) {
            return Optional.empty();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    @Override
    public synchronized void set(String name, ObjectId id) {
        Refs.checkName(name);
        Objects.requireNonNull(id);
        Path tmp = null;
        try {
            tmp = Files.createTempFile(dir, ".tmp-", ".part");
            Files.writeString(tmp, id.hex() + "\n", StandardCharsets.US_ASCII);
            Files.move(tmp, dir.resolve(name), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            tmp = null;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } finally {
            if (tmp != null) {
                try {
                    Files.deleteIfExists(tmp);
                } catch (IOException ignored) {
                    // best effort
                }
            }
        }
    }

    @Override
    public synchronized List<String> names() {
        try (Stream<Path> s = Files.list(dir)) {
            return s.map(p -> p.getFileName().toString()).filter(n -> !n.startsWith(".")).sorted().toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

package ae.vcs;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** In-memory adapter. Thread-safe. */
public final class MemoryObjectStore implements ObjectStore {
    private final Map<ObjectId, byte[]> objects = new HashMap<>();

    @Override
    public synchronized ObjectId put(byte[] raw) {
        Objects.requireNonNull(raw);
        ObjectId id = ObjectId.ofRaw(raw);
        objects.putIfAbsent(id, raw.clone());
        return id;
    }

    @Override
    public synchronized Optional<byte[]> get(ObjectId id) {
        byte[] raw = objects.get(id);
        if (raw == null) {
            return Optional.empty();
        }
        if (!ObjectId.ofRaw(raw).equals(id)) {
            throw new CorruptObjectException("hash mismatch for " + id);
        }
        return Optional.of(raw.clone());
    }

    /** Test hook: replaces stored bytes without rehashing. */
    synchronized void tamper(ObjectId id, byte[] raw) {
        objects.put(id, raw);
    }

    synchronized void remove(ObjectId id) {
        objects.remove(id);
    }
}

