import org.junit.jupiter.api.io.TempDir;

class CodecAndStoreTest {
    // SHA-256 literals computed independently with Python hashlib over "kind len\0payload".
    static final String BLOB_HELLO = "8aec4e4876f854f688d0ebfc8f37598f38e5fd6903cccc850ca36591175aeb60";
    static final String BLOB_EMPTY = "473a0f4c3be8a93681a267e3b1e9a7dcda1185436fe141f7749120a303721813";
    static final String TREE_EMPTY = "6ef19b41225c5369f1c104d45d8d85efa9b057b53b14b4b9b939dd74decc5321";
    static final String TREE_A_HELLO = "0cbf88725565cee21228fd8a480e3cac63891f3a5fd90a4f1dcc1cebf0e16601";

    @Test
    void blobIdsMatchKnownLiterals() {
        assertEquals(BLOB_HELLO, ObjectId.ofRaw(Codec.raw(Codec.BLOB, "hello".getBytes(StandardCharsets.UTF_8))).hex());
        assertEquals(BLOB_EMPTY, ObjectId.ofRaw(Codec.raw(Codec.BLOB, new byte[0])).hex());
    }

    @Test
    void treeIdsMatchKnownLiterals() {
        assertEquals(TREE_EMPTY, ObjectId.ofRaw(Codec.raw(Codec.TREE, Codec.encodeTree(Map.of()))).hex());
        byte[] t = Codec.encodeTree(Map.of("a.txt", new ObjectId(BLOB_HELLO)));
        assertEquals(TREE_A_HELLO, ObjectId.ofRaw(Codec.raw(Codec.TREE, t)).hex());
    }

    @Test
    void treeEncodingIgnoresInsertionOrderAndSortsByUtf8Bytes() {
        ObjectId x = new ObjectId(BLOB_HELLO);
        Map<String, ObjectId> one = new LinkedHashMap<>();
        Map<String, ObjectId> two = new LinkedHashMap<>();
        // UTF-8: U+FF5E = EF BD 9E sorts before U+1F600 = F0 9F 98 80; String.compareTo (UTF-16) says the opposite.
        for (String p : List.of("b", "～", "😀", "a/z", "a/b")) {
            one.put(p, x);
        }
        for (String p : List.of("a/b", "😀", "a/z", "～", "b")) {
            two.put(p, x);
        }
        assertArrayEquals(Codec.encodeTree(one), Codec.encodeTree(two));
        assertEquals(List.of("a/b", "a/z", "b", "～", "😀"),
            List.copyOf(Codec.decodeTree(Codec.encodeTree(one)).keySet()));
    }

    @Test
    void badPathsAreRejected() {
        ObjectId x = new ObjectId(BLOB_HELLO);
        for (String p : List.of("", "/a", "a/", "a//b", "a/./b", "../a", "a\nb", "a\0b")) {
            assertThrows(IllegalArgumentException.class, () -> Codec.encodeTree(Map.of(p, x)), p);
        }
    }

    @Test
    void commitRoundTripsWithAwkwardMessages() {
        ObjectId t = new ObjectId(TREE_EMPTY);
        ObjectId p1 = new ObjectId(BLOB_HELLO);
        ObjectId p2 = new ObjectId(BLOB_EMPTY);
        for (String msg : List.of("", "one line", "two\n\nparagraphs\n", "\n\n", "tree fake\nparent fake\n\nx", "ünï☃")) {
            Commit c = new Commit(t, List.of(p1, p2), "Ann <a@x>", -5L, msg);
            assertEquals(c, Codec.decodeCommit(Codec.encodeCommit(c)), "message: " + msg);
        }
        Commit root = new Commit(t, List.of(), "x", Long.MAX_VALUE, "m");
        assertEquals(root, Codec.decodeCommit(Codec.encodeCommit(root)));
    }

    @Test
    void authorWithNewlineIsRejected() {
        assertThrows(IllegalArgumentException.class,
            () -> new Commit(new ObjectId(TREE_EMPTY), List.of(), "a\nb", 0, "m"));
    }

    @Test
    void decodeRejectsMalformedRawObjects() {
        assertThrows(CorruptObjectException.class, () -> Codec.decode("blob 5".getBytes(StandardCharsets.US_ASCII)));
        assertThrows(CorruptObjectException.class, () -> Codec.decode("blob 5\0abc".getBytes(StandardCharsets.US_ASCII)));
        assertThrows(CorruptObjectException.class, () -> Codec.decode("blob x\0abc".getBytes(StandardCharsets.US_ASCII)));
        assertThrows(CorruptObjectException.class, () -> Codec.decode("blob -1\0".getBytes(StandardCharsets.US_ASCII)));
        assertEquals("blob", Codec.decode("blob 3\0abc".getBytes(StandardCharsets.US_ASCII)).kind());
    }

    @Test
    void objectIdValidatesItsText() {
        assertThrows(IllegalArgumentException.class, () -> new ObjectId("abc"));
        assertThrows(IllegalArgumentException.class, () -> new ObjectId(BLOB_HELLO.toUpperCase()));
        assertEquals(new ObjectId(BLOB_HELLO), ObjectId.parse(BLOB_HELLO.toUpperCase() + "\n"));
    }

    @Test
    void memoryStoreRoundTripDedupAndTamperDetection() {
        MemoryObjectStore s = new MemoryObjectStore();
        byte[] raw = Codec.raw(Codec.BLOB, new byte[] {1, 2, 3});
        ObjectId id = s.put(raw);
        assertEquals(id, s.put(raw));
        raw[0] = 'x'; // caller mutation must not leak in
        assertArrayEquals(Codec.raw(Codec.BLOB, new byte[] {1, 2, 3}), s.get(id).orElseThrow());
        assertEquals(Optional.empty(), s.get(new ObjectId(BLOB_HELLO)));
        s.tamper(id, Codec.raw(Codec.BLOB, new byte[] {9}));
        assertThrows(CorruptObjectException.class, () -> s.get(id));
    }

    @Test
    void fileStoreRoundTripOverwriteAndNoTempFiles(@TempDir Path dir) throws IOException {
        FileObjectStore s = new FileObjectStore(dir.resolve("objs"));
        byte[] raw = Codec.raw(Codec.BLOB, "hello".getBytes(StandardCharsets.UTF_8));
        ObjectId id = s.put(raw);
        assertEquals(BLOB_HELLO, id.hex());
        assertEquals(id, s.put(raw));
        assertArrayEquals(raw, new FileObjectStore(dir.resolve("objs")).get(id).orElseThrow());
        assertTrue(Files.exists(dir.resolve("objs/8a/ec4e4876f854f688d0ebfc8f37598f38e5fd6903cccc850ca36591175aeb60")));
        try (Stream<Path> files = Files.walk(dir.resolve("objs"))) {
            assertEquals(List.of(), files.filter(Files::isRegularFile)
                .filter(p -> p.getFileName().toString().startsWith(".tmp-")).toList());
            assertEquals(1, Files.walk(dir.resolve("objs")).filter(Files::isRegularFile).count());
        }
        assertEquals(Optional.empty(), s.get(new ObjectId(BLOB_EMPTY)));
    }

    @Test
    void fileStoreDetectsEveryFlippedByteAndEveryTruncation(@TempDir Path dir) throws IOException {
        FileObjectStore s = new FileObjectStore(dir);
        byte[] raw = Codec.raw(Codec.BLOB, "some content".getBytes(StandardCharsets.UTF_8));
        ObjectId id = s.put(raw);
        Path file = s.pathOf(id);
        for (int i = 0; i < raw.length; i++) {
            byte[] bad = raw.clone();
            bad[i] ^= 0x01;
            Files.write(file, bad);
            assertThrows(CorruptObjectException.class, () -> s.get(id), "flip at " + i);
        }
        for (int len = 0; len < raw.length; len++) {
            Files.write(file, java.util.Arrays.copyOf(raw, len));
            assertThrows(CorruptObjectException.class, () -> s.get(id), "truncate to " + len);
        }
        Files.write(file, raw);
        assertArrayEquals(raw, s.get(id).orElseThrow());
    }

    @Test
    void fileRefsPersistOverwriteAndRejectBadNames(@TempDir Path dir) throws IOException {
        FileRefs r = new FileRefs(dir.resolve("refs"));
        assertEquals(Optional.empty(), r.get("main"));
        r.set("main", new ObjectId(BLOB_HELLO));
        r.set("dev", new ObjectId(BLOB_EMPTY));
        r.set("main", new ObjectId(TREE_EMPTY));
        FileRefs reopened = new FileRefs(dir.resolve("refs"));
        assertEquals(Optional.of(new ObjectId(TREE_EMPTY)), reopened.get("main"));
        assertEquals(List.of("dev", "main"), reopened.names());
        for (String bad : List.of("", ".hidden", "a/b", "..", "a b", "-x")) {
            assertThrows(IllegalArgumentException.class, () -> r.set(bad, new ObjectId(BLOB_HELLO)), bad);
        }
        Files.writeString(dir.resolve("refs/junk"), "not an id");
        assertThrows(CorruptObjectException.class, () -> reopened.get("junk"));
    }
}

package ae.vcs;

import static org.junit.jupiter.api.Assertions.*;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;

/** Differential tests: brute-force oracles written independently of Repo's algorithms. */
class RandomizedTest {
    private static final String[] PATHS = {"a", "b", "c", "d/x", "d/y", "e/f/g", "h"};

    /** Builds a random DAG of commits on branches; returns every commit with its parents. */
    private static final class World {
        final AtomicLong clock = new AtomicLong();
        final Repo repo;
        final Map<ObjectId, List<ObjectId>> parents = new HashMap<>();
        final List<ObjectId> all = new ArrayList<>();
        final List<String> branches = new ArrayList<>();
        final Random rnd;
        int counter;

        World(long seed) {
            rnd = new Random(seed);
            repo = new Repo(new MemoryObjectStore(), new MemoryRefs(), () -> rnd.nextInt(50)); // skewed times on purpose
        }

        Map<String, byte[]> randomFiles(Map<String, byte[]> from) {
            Map<String, byte[]> next = new TreeMap<>(from);
            String p = PATHS[rnd.nextInt(PATHS.length)];
            if (next.containsKey(p) && rnd.nextInt(3) == 0) {
                next.remove(p);
            } else {
                next.put(p, ("v" + (counter++)).getBytes(StandardCharsets.UTF_8));
            }
            return next;
        }

        void record(ObjectId id) {
            parents.put(id, repo.readCommit(id).parents());
            all.add(id);
        }

        void grow(int steps) {
            branches.add("b0");
            for (int i = 0; i < steps; i++) {
                String br = branches.get(rnd.nextInt(branches.size()));
                int action = rnd.nextInt(10);
                Optional<ObjectId> head = repo.head(br);
                if (head.isEmpty() || action < 6) {
                    Map<String, byte[]> base = head.isPresent() ? repo.checkout(head.get()) : Map.of();
                    Map<String, byte[]> next = randomFiles(base);
                    if (next.equals(base) || (head.isPresent() && sameFiles(next, base))) {
                        continue;
                    }
                    try {
                        record(repo.commit(br, next, "t", "c" + i));
                    } catch (IllegalStateException emptyCommit) {
                        // tree equal to parent's tree: skip
                    }
                } else if (action < 8 && head.isPresent()) {
                    String name = "b" + branches.size();
                    repo.branch(name, head.get());
                    branches.add(name);
                } else {
                    String other = branches.get(rnd.nextInt(branches.size()));
                    if (!other.equals(br) && repo.head(other).isPresent() && head.isPresent()) {
                        MergeResult r = repo.merge(br, other, "t", "m" + i);
                        if (r instanceof MergeResult.Merged m) {
                            record(m.commit());
                        }
                    }
                }
            }
        }

        static boolean sameFiles(Map<String, byte[]> a, Map<String, byte[]> b) {
            if (!a.keySet().equals(b.keySet())) {
                return false;
            }
            for (String k : a.keySet()) {
                if (!java.util.Arrays.equals(a.get(k), b.get(k))) {
                    return false;
                }
            }
            return true;
        }

        Set<ObjectId> ancestors(ObjectId id) {
            Set<ObjectId> out = new HashSet<>();
            List<ObjectId> todo = new ArrayList<>(List.of(id));
            while (!todo.isEmpty()) {
                ObjectId x = todo.remove(todo.size() - 1);
                if (out.add(x)) {
                    todo.addAll(parents.get(x));
                }
            }
            return out;
        }
    }

    @Test
    void mergeBaseAgreesWithBruteForceOnRandomDags() {
        int checked = 0;
        int multi = 0;
        for (long seed = 1; seed <= 40; seed++) {
            World w = new World(seed);
            w.grow(60);
            for (int i = 0; i < 25 && w.all.size() > 1; i++) {
                ObjectId x = w.all.get(w.rnd.nextInt(w.all.size()));
                ObjectId y = w.all.get(w.rnd.nextInt(w.all.size()));
                Set<ObjectId> common = new HashSet<>(w.ancestors(x));
                common.retainAll(w.ancestors(y));
                // best = common ancestors with no strict descendant among the common ancestors
                Set<ObjectId> best = new HashSet<>();
                for (ObjectId c : common) {
                    boolean hasDescendant = false;
                    for (ObjectId d : common) {
                        if (!d.equals(c) && w.ancestors(d).contains(c)) {
                            hasDescendant = true;
                        }
                    }
                    if (!hasDescendant) {
                        best.add(c);
                    }
                }
                Optional<ObjectId> got = w.repo.mergeBase(x, y);
                if (common.isEmpty()) {
                    assertEquals(Optional.empty(), got, "seed " + seed);
                } else {
                    assertTrue(got.isPresent() && best.contains(got.get()), "seed " + seed + " best " + best + " got " + got);
                    assertEquals(got, w.repo.mergeBase(y, x), "symmetry, seed " + seed);
                }
                assertEquals(w.ancestors(x).contains(y), w.repo.isAncestor(y, x), "isAncestor seed " + seed);
                if (best.size() > 1) {
                    multi++;
                }
                checked++;
            }
        }
        assertTrue(checked > 500, "checked " + checked);
        System.out.println("mergeBase pairs checked=" + checked + " with several best ancestors=" + multi);
    }

    @Test
    void logIsATopologicalOrderOfExactlyTheAncestors() {
        for (long seed = 100; seed < 130; seed++) {
            World w = new World(seed);
            w.grow(50);
            for (ObjectId tip : w.all) {
                List<ObjectId> log = w.repo.log(tip);
                assertEquals(w.ancestors(tip), new HashSet<>(log), "seed " + seed);
                assertEquals(log.size(), new HashSet<>(log).size(), "no duplicates, seed " + seed);
                Map<ObjectId, Integer> pos = new HashMap<>();
                for (int i = 0; i < log.size(); i++) {
                    pos.put(log.get(i), i);
                }
                for (ObjectId c : log) {
                    for (ObjectId p : w.parents.get(c)) {
                        assertTrue(pos.get(c) < pos.get(p), "child before parent, seed " + seed);
                    }
                }
                assertEquals(tip, log.get(0));
            }
        }
    }

    /** Independent per-path oracle: returns merged map or null when any path conflicts. */
    private static Map<String, String> oracle(Map<String, String> base, Map<String, String> ours, Map<String, String> theirs) {
        Map<String, String> out = new TreeMap<>();
        Set<String> paths = new HashSet<>();
        paths.addAll(base.keySet());
        paths.addAll(ours.keySet());
        paths.addAll(theirs.keySet());
        for (String p : paths) {
            String b = base.get(p);
            String o = ours.get(p);
            String t = theirs.get(p);
            String pick;
            if (java.util.Objects.equals(o, b)) {
                pick = t;
            } else if (java.util.Objects.equals(t, b) || java.util.Objects.equals(o, t)) {
                pick = o;
            } else {
                return null;
            }
            if (pick != null) {
                out.put(p, pick);
            }
        }
        return out;
    }

    private static Map<String, String> text(Map<String, byte[]> m) {
        Map<String, String> out = new TreeMap<>();
        m.forEach((k, v) -> out.put(k, new String(v, StandardCharsets.UTF_8)));
        return out;
    }

    @Test
    void mergeAgreesWithPerPathOracleAndIsSymmetric() {
        int merged = 0;
        int conflicted = 0;
        for (long seed = 1; seed <= 60; seed++) {
            Random rnd = new Random(seed);
            AtomicLong clock = new AtomicLong();
            Repo repo = new Repo(new MemoryObjectStore(), new MemoryRefs(), clock::incrementAndGet);
            World w = new World(seed);
            Map<String, byte[]> base = new TreeMap<>();
            base.put("a", "0".getBytes(StandardCharsets.UTF_8));
            base.put("d/x", "0".getBytes(StandardCharsets.UTF_8));
            ObjectId root = repo.commit("main", base, "t", "root");
            repo.branch("one", root);
            repo.branch("two", root);
            Map<String, byte[]> sideA = base;
            Map<String, byte[]> sideB = base;
            for (int i = 0, n = 1 + rnd.nextInt(4); i < n; i++) {
                Map<String, byte[]> next = w.randomFiles(sideA);
                if (!World.sameFiles(next, sideA) && noClash(next)) {
                    repo.commit("one", next, "t", "one" + i);
                    sideA = next;
                }
                Map<String, byte[]> next2 = w.randomFiles(sideB);
                if (!World.sameFiles(next2, sideB) && noClash(next2)) {
                    repo.commit("two", next2, "t", "two" + i);
                    sideB = next2;
                }
            }
            Optional<ObjectId> tipA = repo.head("one");
            Optional<ObjectId> tipB = repo.head("two");
            if (tipA.equals(Optional.of(root)) || tipB.equals(Optional.of(root))) {
                continue; // fast-forward / up-to-date cases are covered elsewhere
            }
            repo.branch("one2", tipA.orElseThrow());
            repo.branch("two2", tipB.orElseThrow());
            Map<String, String> expected = oracle(text(base), text(sideA), text(sideB));
            MergeResult ab = repo.merge("one", "two", "t", "ab");
            MergeResult ba = repo.merge("two2", "one2", "t", "ba");
            if (expected == null || hasClash(expected)) {
                assertInstanceOf(MergeResult.Conflicted.class, ab, "seed " + seed);
                assertInstanceOf(MergeResult.Conflicted.class, ba, "seed " + seed);
                MergeResult.Conflicted ca = (MergeResult.Conflicted) ab;
                MergeResult.Conflicted cb = (MergeResult.Conflicted) ba;
                assertEquals(ca.conflicts().stream().map(Conflict::path).toList(),
                    cb.conflicts().stream().map(Conflict::path).toList(), "symmetric paths, seed " + seed);
                assertEquals(tipA, repo.head("one"));
                conflicted++;
            } else {
                assertInstanceOf(MergeResult.Merged.class, ab, "seed " + seed);
                assertInstanceOf(MergeResult.Merged.class, ba, "seed " + seed);
                assertEquals(expected, text(repo.checkout(((MergeResult.Merged) ab).commit())), "oracle, seed " + seed);
                assertEquals(repo.readCommit(((MergeResult.Merged) ab).commit()).tree(),
                    repo.readCommit(((MergeResult.Merged) ba).commit()).tree(), "same tree either direction, seed " + seed);
                merged++;
            }
        }
        assertTrue(merged >= 10 && conflicted >= 10, "merged=" + merged + " conflicted=" + conflicted);
        System.out.println("merge cases: merged=" + merged + " conflicted=" + conflicted);
    }

    private static boolean noClash(Map<String, byte[]> files) {
        return Codec.findFileDirectoryClash(files.keySet()) == null;
    }

    private static boolean hasClash(Map<String, String> files) {
        return Codec.findFileDirectoryClash(files.keySet()) != null;
    }
}

package ae.vcs;

import static org.junit.jupiter.api.Assertions.*;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class RepoTest {
    MemoryObjectStore store;
    Repo repo;
    AtomicLong clock;

    @BeforeEach
    void setUp() {
        store = new MemoryObjectStore();
        clock = new AtomicLong(100);
        repo = new Repo(store, new MemoryRefs(), () -> clock.incrementAndGet());
    }

    static Map<String, byte[]> files(String... kv) {
        Map<String, byte[]> m = new LinkedHashMap<>();
        for (int i = 0; i < kv.length; i += 2) {
            m.put(kv[i], kv[i + 1].getBytes(StandardCharsets.UTF_8));
        }
        return m;
    }

    static Map<String, String> text(Map<String, byte[]> m) {
        Map<String, String> out = new LinkedHashMap<>();
        m.forEach((k, v) -> out.put(k, new String(v, StandardCharsets.UTF_8)));
        return out;
    }

    ObjectId c(String branch, String... kv) {
